import * as React from "react";
import "./rich.css";
import { sanitizeRichtextHtml } from "@/registry/p1/internal/sanitize-richtext";

/**
 * Renders the value of a Puck `richtext` field.
 *
 * A `richtext` field's value reaches `render` in one of two shapes:
 *   1. A stored **HTML string** — when the page is published or first mounts.
 *   2. A live **ReactNode** — while being edited inline on the Puck canvas.
 *
 * Strings are sanitized before rendering; ReactNodes pass through unchanged.
 */
export interface RichValueProps {
  value: unknown;
  className?: string;
}

/** @deprecated Use `p1-rich` className directly. Removed when accordion/rich-text/tabs convert. */
export const RICH_PROSE = "p1-rich";

export function RichValue({ value, className }: RichValueProps) {
  const cls = ["p1-rich", className].filter(Boolean).join(" ");
  if (value == null || value === "") return null;
  if (typeof value === "string") {
    return <div className={cls} dangerouslySetInnerHTML={{ __html: sanitizeRichtextHtml(value) }} />;
  }
  return <div className={cls}>{value as React.ReactNode}</div>;
}

.p1-rich {
  max-inline-size: 65ch;
  text-wrap: pretty;
}

.p1-rich > *:first-child { margin-block-start: 0; }
.p1-rich > *:last-child { margin-block-end: 0; }

.p1-rich p {
  margin-block-end: var(--p1-space-md);
  line-height: var(--p1-leading-normal);
  color: var(--p1-fg-muted);
}

.p1-rich h2 {
  margin-block: var(--p1-space-md) var(--p1-space-sm);
  font-size: var(--p1-text-2xl);
  font-weight: var(--p1-weight-bold);
  letter-spacing: -0.025em;
  color: var(--p1-fg-default);
}

@media (width >= 48rem) {
  .p1-rich h2 {
    font-size: var(--p1-text-3xl);
  }
}

.p1-rich h3 {
  margin-block: var(--p1-space-sm);
  font-size: var(--p1-text-xl);
  font-weight: var(--p1-weight-bold);
  letter-spacing: -0.025em;
  color: var(--p1-fg-default);
}

.p1-rich ul {
  margin-block-end: var(--p1-space-md);
  list-style: disc;
  padding-inline-start: 1.25rem;
}

.p1-rich ol {
  margin-block-end: var(--p1-space-md);
  list-style: decimal;
  padding-inline-start: 1.25rem;
}

.p1-rich li {
  margin-block-end: 0.25rem;
  line-height: var(--p1-leading-normal);
  color: var(--p1-fg-muted);
}

.p1-rich blockquote {
  margin-block: var(--p1-space-md);
  border-inline-start: 4px solid var(--p1-warning);
  padding-inline-start: var(--p1-space-md);
  font-size: var(--p1-text-xl);
  font-style: italic;
  line-height: var(--p1-leading-normal);
  color: var(--p1-fg-default);
}

.p1-rich strong {
  font-weight: var(--p1-weight-medium);
  color: var(--p1-fg-default);
}

.p1-rich em {
  font-style: italic;
}

.p1-rich a {
  color: var(--p1-accent);
  text-decoration: underline;
}

.p1-rich mark {
  border-radius: var(--p1-radius-sm);
  background: color-mix(in oklch, var(--p1-warning) 40%, transparent);
  padding-inline: 0.125rem;
  color: var(--p1-fg-default);
}

.p1-rich code {
  border-radius: var(--p1-radius-sm);
  background: var(--p1-surface-code);
  padding-inline: 0.25rem;
  padding-block: 0.125rem;
  font-family: monospace;
  font-size: 0.9em;
}

import DOMPurify from "isomorphic-dompurify";

/**
 * Sanitize richtext HTML before rendering via `dangerouslySetInnerHTML`.
 *
 * Allowlist matches what the Puck richtext toolbar can produce; anything
 * else — `<script>`, `<img onerror>`, `javascript:`/`data:` hrefs — is
 * stripped. Runs in both Node (SSR) and the browser via isomorphic-dompurify.
 */
const ALLOWED_TAGS = [
  "p", "br", "strong", "b", "em", "i", "u", "s",
  "ul", "ol", "li", "a", "code", "span",
  "h2", "h3", "blockquote", "mark",
];

const ALLOWED_ATTR = ["href", "target", "rel"];

export function sanitizeRichtextHtml(html: string): string {
  return DOMPurify.sanitize(html, {
    ALLOWED_TAGS,
    ALLOWED_ATTR,
    ALLOWED_URI_REGEXP: /^(?:https?:|mailto:|tel:|ftp:|#|\/|\.)/i,
  });
}
